namespace{std::mutex s_lock;std::unordered_map<std::string,std::weak_ptr<CAnimData>>s_cache;std::string Key(const char*s){std::string k=s?s:"";std::transform(k.begin(),k.end(),k.begin(),[](unsigned char c){return static_cast<char>(std::tolower(c));});return k;}}
void AnimInitialize(){std::lock_guard g(s_lock);s_cache.clear();}void AnimDestroy(){std::lock_guard g(s_lock);s_cache.clear();}unsigned AnimGetReferenceCount(const std::shared_ptr<CAnimData>&a){return a?static_cast<unsigned>(a.use_count()):0;}std::shared_ptr<CAnimData>GetAnim(const char*n){std::lock_guard g(s_lock);auto i=s_cache.find(Key(n));return i==s_cache.end()?nullptr:i->second.lock();}void HashNewAnim(const char*n,const std::shared_ptr<CAnimData>&a){if(!n||!a)return;std::lock_guard g(s_lock);s_cache[Key(n)]=a;}
namespace{void CopyName(char(&dst)[80],const std::string&src){std::memset(dst,0,sizeof(dst));std::memcpy(dst,src.data(),(std::min)(src.size(),sizeof(dst)-1));}unsigned TranslateId(const std::vector<unsigned>&ids,unsigned id){return id<ids.size()?ids[id]:~0U;}void CollectObject(const MDLGENOBJECT&o,unsigned&maxId){maxId=(std::max)(maxId,o.objectId);}}
unsigned AnimBuildObjectIdTranslation(const MDLDATA&mdl,std::vector<unsigned>&ids){unsigned maxId=0;for(auto&v:mdl.bones)CollectObject(v.object,maxId);for(auto&v:mdl.hitTests)CollectObject(v.object,maxId);for(auto&v:mdl.lights)CollectObject(v.object,maxId);for(auto&v:mdl.helpers)CollectObject(v,maxId);for(auto&v:mdl.attachments)CollectObject(v.object,maxId);for(auto&v:mdl.emitters)CollectObject(v.object,maxId);for(auto&v:mdl.ribbons)CollectObject(v.object,maxId);for(auto&v:mdl.events)CollectObject(v.object,maxId);ids.assign(maxId+1,~0U);unsigned next=0;auto add=[&](const MDLGENOBJECT&o){if(ids[o.objectId]!=~0U)throw std::runtime_error("duplicate animation object id");ids[o.objectId]=next++;};for(auto&v:mdl.bones)add(v.object);for(auto&v:mdl.hitTests)add(v.object);for(auto&v:mdl.lights)add(v.object);for(auto&v:mdl.helpers)add(v);for(auto&v:mdl.attachments)add(v.object);for(auto&v:mdl.emitters)add(v.object);for(auto&v:mdl.ribbons)add(v.object);for(auto&v:mdl.events)add(v.object);return next;}
unsigned CountSectionEntries(std::span<const std::byte>file,std::uint32_t tag){std::size_t p=file.size()>=4&&std::memcmp(file.data(),"MDLX",4)==0?4:0;for(;p+8<=file.size();){std::uint32_t found=0,size=0,count=0;std::memcpy(&found,file.data()+p,4);std::memcpy(&size,file.data()+p+4,4);if(size>file.size()-p-8)throw std::runtime_error("truncated animation section");if(found==tag){if(size<4)throw std::runtime_error("invalid counted animation section");std::memcpy(&count,file.data()+p+8,4);return count;}p+=8+size;}if(p!=file.size())throw std::runtime_error("truncated animation section header");return 0;}
unsigned GetObjectFlags(unsigned flags){unsigned result=0;if(flags&8U)result=56;else if(flags&0x10U)result=8;else if(flags&0x20U)result=16;else if(flags&0x40U)result=32;if(flags&1U)result|=1;if(flags&2U)result|=2;if(flags&4U)result|=4;if(flags&0x4000U)result|=0x40;return result;}
KEYTYPE GetTrackType(MDLTRACKTYPE source,MDLTRACKTYPE force){if(source>=NUM_TRACK_TYPES||force>NUM_TRACK_TYPES)throw std::runtime_error("invalid animation track type");if(force==TRACK_NO_INTERP)source=TRACK_NO_INTERP;else if(force==TRACK_LINEAR&&source>TRACK_LINEAR)source=TRACK_LINEAR;return static_cast<KEYTYPE>(source);}
void GenericHandlerAnim(CAnimData&data,CAnimObj&out,const MDLGENOBJECT&in,const std::vector<unsigned>&ids,MDLTRACKTYPE force){CopyName(out.name,in.name);unsigned translated=TranslateId(ids,in.objectId);if(translated==~0U)throw std::runtime_error("invalid animation object id");AnimObjectSetIndex(data,out,translated);out.flags=static_cast<std::uint8_t>(GetObjectFlags(in.flags));AddKeyFrames(out.translation,in.transkeys,force);AddKeyFrames<NTempest::C4QuaternionCompressed>(out.rotation,in.rotkeys,force);AddKeyFrames(out.scale,in.scalekeys,force);}
CAnimBoneObj*CreateBone(CAnimData&d,const MDLBONE&in,const std::vector<unsigned>&ids,MDLTRACKTYPE force){auto*out=AnimObjectCreateBone(d);GenericHandlerAnim(d,*out,in.object,ids,force);out->geosetId=in.geosetId<0?0xFF:static_cast<std::uint8_t>(in.geosetId);return out;}CAnimBoneObj*CreateHitTestShape(CAnimData&d,const MDLBONE&in,const std::vector<unsigned>&ids,MDLTRACKTYPE force){auto*out=CreateBone(d,in,ids,force);out->geosetId=0xFF;return out;}
CAnimLightObj*CreateLight(CAnimData&d,const MDLLIGHTSECTION&in,const std::vector<unsigned>&ids,MDLTRACKTYPE force){auto*out=AnimObjectCreateLight(d);GenericHandlerAnim(d,*out,in.object,ids,force);out->lightType=in.type;out->baseAttenStart=in.attenuationStartValue;out->baseAttenEnd=in.attenuationEndValue;out->baseColor=in.colorValue;out->baseIntensity=in.intensityValue;out->baseAmbientColor=in.ambientColorValue;out->baseAmbientIntensity=in.ambientIntensityValue;AddKeyFrames(out->attenstart,in.attenuationStart,force);AddKeyFrames(out->attenend,in.attenuationEnd,force);AddKeyFrames(out->color,in.color,force);AddKeyFrames(out->intensity,in.intensity,force);AddKeyFrames(out->ambColor,in.ambientColor,force);AddKeyFrames(out->ambIntensity,in.ambientIntensity,force);AddKeyFrames(out->visibility,in.visibility,force);return out;}
CAnimEmitter2Obj*CreateParticleEmitter2(CAnimData&d,const MDLPARTICLEEMITTER2ANIM&in,const std::vector<unsigned>&ids,MDLTRACKTYPE force){auto*out=AnimObjectCreateEmitter2(d);GenericHandlerAnim(d,*out,in.object,ids,force);out->squirts=in.squirts;AddKeyFrames(out->particleSpeed,in.speed,force);AddKeyFrames(out->variation,in.variation,force);AddKeyFrames(out->latitude,in.latitude,force);AddKeyFrames(out->longitude,in.longitude,force);AddKeyFrames(out->gravity,in.gravity,force);AddKeyFrames(out->lifeSpan,in.lifeSpan,force);AddKeyFrames(out->emissionRate,in.emissionRate,force);AddKeyFrames(out->length,in.length,force);AddKeyFrames(out->width,in.width,force);AddKeyFrames(out->zsource,in.zsource,force);AddKeyFrames(out->visibility,in.visibility,force);return out;}
CAnimRibbonObj*CreateRibbonEmitter(CAnimData&d,const MDLRIBBONEMITTERANIM&in,const std::vector<unsigned>&ids,MDLTRACKTYPE force){auto*out=AnimObjectCreateRibbon(d);GenericHandlerAnim(d,*out,in.object,ids,force);AddKeyFrames(out->heightAbove,in.heightAbove,force);AddKeyFrames(out->heightBelow,in.heightBelow,force);AddKeyFrames(out->alpha,in.alpha,force);AddKeyFrames(out->visibility,in.visibility,force);AddKeyFrames(out->color,in.color,force);AddKeyFrames(out->slot,in.slot,force);return out;}
CAnimEventObj*CreateEventObject(CAnimData&d,const MDLEVENTSECTION&in,const std::vector<unsigned>&ids,MDLTRACKTYPE force){auto*out=AnimObjectCreateEvent(d);GenericHandlerAnim(d,*out,in.object,ids,force);AnimObjectSetEventTrack(*out,in.eventTimes);return out;}CAnimObj*CreateHelper(CAnimData&d,const MDLGENOBJECT&in,const std::vector<unsigned>&ids,MDLTRACKTYPE force){auto*out=AnimObjectCreateHelper(d);GenericHandlerAnim(d,*out,in,ids,force);return out;}CAnimObj*CreateAttachmentPoint(CAnimData&d,const MDLATTACHMENT&in,const std::vector<unsigned>&ids,MDLTRACKTYPE force){auto*out=AnimObjectCreateAttachment(d);GenericHandlerAnim(d,*out,in.object,ids,force);out->geosetId=in.geosetId;AddKeyFrames(out->visibility,in.visibility,force);return out;}
void IAnimCreateObjects(CAnimData&d,const MDLDATA&mdl,unsigned flags,const std::vector<unsigned>&ids,MDLTRACKTYPE force){for(auto&v:mdl.bones)CreateBone(d,v,ids,force);if(flags&1U)for(auto&v:mdl.hitTests)CreateHitTestShape(d,v,ids,force);if((flags&2U)==0)for(auto&v:mdl.lights)CreateLight(d,v,ids,force);for(auto&v:mdl.helpers)CreateHelper(d,v,ids,force);for(auto&v:mdl.attachments)CreateAttachmentPoint(d,v,ids,force);for(auto&v:mdl.emitters)CreateParticleEmitter2(d,v,ids,force);for(auto&v:mdl.ribbons)CreateRibbonEmitter(d,v,ids,force);for(auto&v:mdl.events)CreateEventObject(d,v,ids,force);}
void MaterialHandlerAnim(CAnimData&d,const MDLDATA&m,MDLTRACKTYPE){AnimAddMaterialLayers(d,m.materials);}void GeosetHandlerAnim(CAnimData&d,const MDLDATA&m,MDLTRACKTYPE){AnimAddGeosets(d,m.geosets);}void CameraHandlerAnim(CAnimData&d,const MDLDATA&m,MDLTRACKTYPE){AnimAddCameras(d,m.cameras);}
bool AnimBuild(CAnimData&d,const MDLDATA&mdl,unsigned flags){AnimInit(d);d.seq=mdl.sequences;d.globalSeqLength=mdl.globalSequences;d.tex=mdl.textureAnims;MaterialHandlerAnim(d,mdl,(flags&4U)?TRACK_LINEAR:NUM_TRACK_TYPES);GeosetHandlerAnim(d,mdl,(flags&4U)?TRACK_LINEAR:NUM_TRACK_TYPES);CameraHandlerAnim(d,mdl,(flags&4U)?TRACK_LINEAR:NUM_TRACK_TYPES);std::vector<unsigned>ids;AnimBuildObjectIdTranslation(mdl,ids);IAnimCreateObjects(d,mdl,flags,ids,(flags&4U)?TRACK_LINEAR:NUM_TRACK_TYPES);d.pivots.assign(d.obj.size(),{});auto setup=[&](const MDLGENOBJECT&o){unsigned child=TranslateId(ids,o.objectId),p=TranslateId(ids,o.parentId);if(child<d.obj.size()){if(o.objectId<mdl.pivotPoints.size())d.pivots[child]=mdl.pivotPoints[o.objectId];if(o.parentId!=~0U){if(p>=d.obj.size())throw std::runtime_error("invalid animation parent id");AnimObjectSetParent(d,*d.obj[child],d.obj[p]);}}};for(auto&v:mdl.bones)setup(v.object);for(auto&v:mdl.hitTests)setup(v.object);for(auto&v:mdl.lights)setup(v.object);for(auto&v:mdl.helpers)setup(v);for(auto&v:mdl.attachments)setup(v.object);for(auto&v:mdl.emitters)setup(v.object);for(auto&v:mdl.ribbons)setup(v.object);for(auto&v:mdl.events)setup(v.object);BuildHierarchy(d);ValidateInheritanceFlags(d);AnimSetSequenceOrderingDefault(d);AnimResetObjectOrdering(d);return true;}std::shared_ptr<CAnimData>AnimBuild(const MDLDATA&mdl,unsigned flags){auto d=AnimCreate();AnimBuild(*d,mdl,flags);return d;}

namespace{
constexpr std::uint32_t FourCC(char a,char b,char c,char d){return std::uint32_t(std::uint8_t(a))|(std::uint32_t(std::uint8_t(b))<<8)|(std::uint32_t(std::uint8_t(c))<<16)|(std::uint32_t(std::uint8_t(d))<<24);}
struct ByteReader{std::span<const std::byte> bytes;std::size_t pos=0;std::size_t left()const{return bytes.size()-pos;}template<class T>T pod(){if(left()<sizeof(T))throw std::runtime_error("truncated animation data");T v{};std::memcpy(&v,bytes.data()+pos,sizeof(T));pos+=sizeof(T);return v;}std::span<const std::byte> take(std::size_t n){if(n>left())throw std::runtime_error("truncated animation data");auto s=bytes.subspan(pos,n);pos+=n;return s;}};
template<class T>void ReadBinaryTrack(ByteReader&r,MDLKEYTRACK<T>&track,const std::vector<CAnimSequence>&seq){const auto count=r.pod<std::uint32_t>();const auto type=r.pod<std::uint32_t>();track.type=static_cast<MDLTRACKTYPE>(type);if(track.type>=NUM_TRACK_TYPES)throw std::runtime_error("invalid binary animation track type");track.globalSequence=r.pod<std::uint32_t>();track.keys.reserve(count);for(unsigned i=0;i<count;++i){MDLKEYFRAME<T>k;k.time=r.pod<std::int32_t>();k.value=r.pod<T>();if(track.type>=TRACK_HERMITE){k.inTan=r.pod<T>();k.outTan=r.pod<T>();}if(track.globalSequence==~0U){for(unsigned s=0;s<seq.size();++s)if(k.time>=seq[s].start&&k.time<=seq[s].end){k.sequence=s;break;}}track.keys.push_back(k);}}
void ReadBinaryQuaternionTrack(ByteReader&r,MDLKEYTRACK<NTempest::C4Quaternion>&track,const std::vector<CAnimSequence>&seq){const auto count=r.pod<std::uint32_t>();track.type=static_cast<MDLTRACKTYPE>(r.pod<std::uint32_t>());if(track.type>=NUM_TRACK_TYPES)throw std::runtime_error("invalid binary quaternion track type");track.globalSequence=r.pod<std::uint32_t>();auto read=[&](){return static_cast<NTempest::C4Quaternion>(r.pod<NTempest::C4QuaternionCompressed>());};for(unsigned i=0;i<count;++i){MDLKEYFRAME<NTempest::C4Quaternion>k;k.time=r.pod<std::int32_t>();k.value=read();if(track.type>=TRACK_HERMITE){k.inTan=read();k.outTan=read();}if(track.globalSequence==~0U)for(unsigned s=0;s<seq.size();++s)if(k.time>=seq[s].start&&k.time<=seq[s].end){k.sequence=s;break;}track.keys.push_back(k);}}
MDLGENOBJECT ReadGenericObject(ByteReader&r,const std::vector<CAnimSequence>&seq){const auto start=r.pos;const auto size=r.pod<std::uint32_t>();if(size<96||size>r.bytes.size()-start)throw std::runtime_error("invalid generic animation object size");MDLGENOBJECT out;auto name=r.take(80);const char*chars=reinterpret_cast<const char*>(name.data());std::size_t len=0;while(len<name.size()&&chars[len])++len;out.name.assign(chars,len);out.objectId=r.pod<std::uint32_t>();out.parentId=r.pod<std::uint32_t>();out.flags=r.pod<std::uint32_t>();while(r.pos<start+size){if(start+size-r.pos<4)throw std::runtime_error("truncated generic animation track");auto tag=r.pod<std::uint32_t>();if(tag==FourCC('K','G','T','R'))ReadBinaryTrack(r,out.transkeys,seq);else if(tag==FourCC('K','G','R','T'))ReadBinaryQuaternionTrack(r,out.rotkeys,seq);else if(tag==FourCC('K','G','S','C'))ReadBinaryTrack(r,out.scalekeys,seq);else throw std::runtime_error("unknown generic animation track");if(r.pos>start+size)throw std::runtime_error("generic animation track exceeds object");}return out;}
void ReadSequences(std::span<const std::byte>payload,MDLDATA&mdl){ByteReader r{payload};const auto count=r.pod<std::uint32_t>();if(count>255||r.left()!=std::size_t(count)*140)throw std::runtime_error("invalid SEQS section");mdl.sequences.reserve(count);for(unsigned i=0;i<count;++i){auto record=r.take(140);CAnimSequence s{};std::memcpy(s.name,record.data(),80);std::memcpy(&s.start,record.data()+80,4);std::memcpy(&s.end,record.data()+84,4);std::memcpy(&s.moveSpeed,record.data()+88,4);std::memcpy(&s.flags,record.data()+92,4);std::memcpy(&s.boundsRadius,record.data()+96,4);std::memcpy(&s.boundsMin,record.data()+100,12);std::memcpy(&s.boundsMax,record.data()+112,12);float frequency=0;std::memcpy(&frequency,record.data()+124,4);s.randPickChance=static_cast<unsigned>(std::lround(frequency*32767.0F));std::memcpy(&s.replayMin,record.data()+128,4);std::memcpy(&s.replayMax,record.data()+132,4);std::memcpy(&s.blendTime,record.data()+136,4);mdl.sequences.push_back(s);}}
void ReadGlobalSequences(std::span<const std::byte>payload,MDLDATA&mdl){if(payload.size()%4)throw std::runtime_error("invalid GLBS section");ByteReader r{payload};while(r.left())mdl.globalSequences.push_back(r.pod<std::uint32_t>());}
void ReadPivotPoints(std::span<const std::byte>payload,MDLDATA&mdl){if(payload.size()%sizeof(NTempest::C3Vector))throw std::runtime_error("invalid PIVT section");ByteReader r{payload};mdl.pivotPoints.reserve(payload.size()/sizeof(NTempest::C3Vector));while(r.left())mdl.pivotPoints.push_back(r.pod<NTempest::C3Vector>());}
void ReadBones(std::span<const std::byte>payload,MDLDATA&mdl,bool hitTest){ByteReader r{payload};const auto count=r.pod<std::uint32_t>();auto&out=hitTest?mdl.hitTests:mdl.bones;out.reserve(count);for(unsigned i=0;i<count;++i){MDLBONE bone;bone.object=ReadGenericObject(r,mdl.sequences);bone.geosetId=static_cast<int>(r.pod<std::uint32_t>());(void)r.pod<std::uint32_t>();out.push_back(std::move(bone));}if(r.left())throw std::runtime_error("trailing bone animation data");}
void ReadHelpers(std::span<const std::byte>payload,MDLDATA&mdl){ByteReader r{payload};const auto count=r.pod<std::uint32_t>();mdl.helpers.reserve(count);for(unsigned i=0;i<count;++i)mdl.helpers.push_back(ReadGenericObject(r,mdl.sequences));if(r.left())throw std::runtime_error("trailing helper animation data");}
void ReadEvents(std::span<const std::byte>payload,MDLDATA&mdl){ByteReader r{payload};const auto count=r.pod<std::uint32_t>();mdl.events.reserve(count);for(unsigned i=0;i<count;++i){const auto outerStart=r.pos;const auto outerSize=r.pod<std::uint32_t>();if(outerSize<8||outerSize>r.bytes.size()-outerStart)throw std::runtime_error("invalid event object size");const auto outerEnd=outerStart+outerSize;MDLEVENTSECTION e;e.object=ReadGenericObject(r,mdl.sequences);if(r.pos<outerEnd){if(r.pod<std::uint32_t>()!=FourCC('K','E','V','T'))throw std::runtime_error("missing KEVT event track");const auto keys=r.pod<std::uint32_t>();(void)r.pod<std::uint32_t>();e.eventTimes.reserve(keys);for(unsigned k=0;k<keys;++k)e.eventTimes.push_back(r.pod<std::int32_t>());}if(r.pos!=outerEnd)throw std::runtime_error("event object size mismatch");mdl.events.push_back(std::move(e));}if(r.left())throw std::runtime_error("trailing event animation data");}
void ReadLights(std::span<const std::byte>payload,MDLDATA&mdl){ByteReader r{payload};const auto count=r.pod<std::uint32_t>();mdl.lights.reserve(count);for(unsigned i=0;i<count;++i){const auto outerStart=r.pos;const auto outerSize=r.pod<std::uint32_t>();if(outerSize<4+96+44||outerSize>r.bytes.size()-outerStart)throw std::runtime_error("invalid light object size");MDLLIGHTSECTION light;light.object=ReadGenericObject(r,mdl.sequences);light.type=r.pod<std::uint32_t>();light.attenuationStartValue=r.pod<float>();light.attenuationEndValue=r.pod<float>();light.colorValue=r.pod<C3Color>();light.intensityValue=r.pod<float>();light.ambientColorValue=r.pod<C3Color>();light.ambientIntensityValue=r.pod<float>();while(r.pos<outerStart+outerSize){const auto tag=r.pod<std::uint32_t>();if(tag==FourCC('K','L','A','S'))ReadBinaryTrack(r,light.attenuationStart,mdl.sequences);else if(tag==FourCC('K','L','A','E'))ReadBinaryTrack(r,light.attenuationEnd,mdl.sequences);else if(tag==FourCC('K','L','A','C'))ReadBinaryTrack(r,light.color,mdl.sequences);else if(tag==FourCC('K','L','A','I'))ReadBinaryTrack(r,light.intensity,mdl.sequences);else if(tag==FourCC('K','L','B','C'))ReadBinaryTrack(r,light.ambientColor,mdl.sequences);else if(tag==FourCC('K','L','B','I'))ReadBinaryTrack(r,light.ambientIntensity,mdl.sequences);else if(tag==FourCC('K','L','A','V'))ReadBinaryTrack(r,light.visibility,mdl.sequences);else throw std::runtime_error("unknown light animation track");if(r.pos>outerStart+outerSize)throw std::runtime_error("light track exceeds object");}mdl.lights.push_back(std::move(light));}if(r.left())throw std::runtime_error("trailing light animation data");}
void ReadAttachments(std::span<const std::byte>payload,MDLDATA&mdl)
{
    ByteReader r{payload};
    const auto count=r.pod<std::uint32_t>();
    // The second section-header word is the highest parent geoset-animation
    // id.  It is metadata for the MDL writer, not the first object size.
    (void)r.pod<std::uint32_t>();
    mdl.attachments.reserve(count);
    for(unsigned i=0;i<count;++i){
        const auto outerStart=r.pos;
        const auto outerSize=r.pod<std::uint32_t>();
        const auto outerEnd=outerStart+outerSize;
        if(outerSize<4+96+4+1+260||outerEnd>r.bytes.size())
            throw std::runtime_error("invalid attachment object size");
        MDLATTACHMENT attachment;
        attachment.object=ReadGenericObject(r,mdl.sequences);
        // Per-object static data is written directly: attachment id, parent
        // geoset-animation id, then the fixed 260-byte path.  There is no
        // nested static-block size word in this early format.
        attachment.attachmentId=r.pod<std::uint32_t>();
        attachment.geosetId=r.pod<std::uint8_t>();
        r.take(260);
        while(r.pos<outerEnd){
            const auto tag=r.pod<std::uint32_t>();
            if(tag!=FourCC('K','V','I','S'))
                throw std::runtime_error("unknown attachment animation track");
            ReadBinaryTrack(r,attachment.visibility,mdl.sequences);
            if(r.pos>outerEnd)throw std::runtime_error("attachment track exceeds object");
        }
        if(r.pos!=outerEnd)throw std::runtime_error("attachment object size mismatch");
        mdl.attachments.push_back(std::move(attachment));
    }
    if(r.left())throw std::runtime_error("trailing attachment animation data");
}
std::size_t SkipStaticBlock(ByteReader&r,std::size_t outerEnd){const auto start=r.pos;const auto size=r.pod<std::uint32_t>();if(size<4||size>outerEnd-start)throw std::runtime_error("invalid animation static block");r.pos=start+size;return r.pos;}
void ReadEmitters(std::span<const std::byte>payload,MDLDATA&mdl){ByteReader r{payload};const auto count=r.pod<std::uint32_t>();mdl.emitters.reserve(count);for(unsigned i=0;i<count;++i){const auto outerStart=r.pos;const auto outerSize=r.pod<std::uint32_t>();const auto outerEnd=outerStart+outerSize;if(outerSize<8||outerEnd>r.bytes.size())throw std::runtime_error("invalid particle emitter object size");MDLPARTICLEEMITTER2ANIM e;e.object=ReadGenericObject(r,mdl.sequences);SkipStaticBlock(r,outerEnd);e.squirts=r.pod<std::uint32_t>();while(r.pos<outerEnd){const auto tag=r.pod<std::uint32_t>();if(tag==FourCC('K','P','2','E'))ReadBinaryTrack(r,e.emissionRate,mdl.sequences);else if(tag==FourCC('K','P','2','G'))ReadBinaryTrack(r,e.gravity,mdl.sequences);else if(tag==FourCC('K','P','L','N'))ReadBinaryTrack(r,e.longitude,mdl.sequences);else if(tag==FourCC('K','P','2','L'))ReadBinaryTrack(r,e.latitude,mdl.sequences);else if(tag==FourCC('K','P','2','S'))ReadBinaryTrack(r,e.speed,mdl.sequences);else if(tag==FourCC('K','P','2','R'))ReadBinaryTrack(r,e.variation,mdl.sequences);else if(tag==FourCC('K','P','2','N'))ReadBinaryTrack(r,e.length,mdl.sequences);else if(tag==FourCC('K','P','2','W'))ReadBinaryTrack(r,e.width,mdl.sequences);else if(tag==FourCC('K','P','2','Z'))ReadBinaryTrack(r,e.zsource,mdl.sequences);else if(tag==FourCC('K','V','I','S'))ReadBinaryTrack(r,e.visibility,mdl.sequences);else if(tag==FourCC('K','L','I','F'))ReadBinaryTrack(r,e.lifeSpan,mdl.sequences);else throw std::runtime_error("unknown particle emitter animation track");if(r.pos>outerEnd)throw std::runtime_error("particle track exceeds object");}mdl.emitters.push_back(std::move(e));}if(r.left())throw std::runtime_error("trailing particle emitter data");}
void ReadRibbons(std::span<const std::byte>payload,MDLDATA&mdl){ByteReader r{payload};const auto count=r.pod<std::uint32_t>();mdl.ribbons.reserve(count);for(unsigned i=0;i<count;++i){const auto outerStart=r.pos;const auto outerSize=r.pod<std::uint32_t>();const auto outerEnd=outerStart+outerSize;if(outerSize<8||outerEnd>r.bytes.size())throw std::runtime_error("invalid ribbon object size");MDLRIBBONEMITTERANIM ribbon;ribbon.object=ReadGenericObject(r,mdl.sequences);SkipStaticBlock(r,outerEnd);while(r.pos<outerEnd){const auto tag=r.pod<std::uint32_t>();if(tag==FourCC('K','R','H','A'))ReadBinaryTrack(r,ribbon.heightAbove,mdl.sequences);else if(tag==FourCC('K','R','H','B'))ReadBinaryTrack(r,ribbon.heightBelow,mdl.sequences);else if(tag==FourCC('K','R','A','L'))ReadBinaryTrack(r,ribbon.alpha,mdl.sequences);else if(tag==FourCC('K','R','C','O'))ReadBinaryTrack(r,ribbon.color,mdl.sequences);else if(tag==FourCC('K','R','T','X'))ReadBinaryTrack(r,ribbon.slot,mdl.sequences);else if(tag==FourCC('K','V','I','S'))ReadBinaryTrack(r,ribbon.visibility,mdl.sequences);else throw std::runtime_error("unknown ribbon animation track");if(r.pos>outerEnd)throw std::runtime_error("ribbon track exceeds object");}mdl.ribbons.push_back(std::move(ribbon));}if(r.left())throw std::runtime_error("trailing ribbon data");}
void ReadCameras(std::span<const std::byte>payload,MDLDATA&mdl){ByteReader r{payload};const auto count=r.pod<std::uint32_t>();mdl.cameras.reserve(count);for(unsigned i=0;i<count;++i){const auto start=r.pos;const auto size=r.pod<std::uint32_t>();const auto end=start+size;if(size<120||end>r.bytes.size())throw std::runtime_error("invalid camera animation size");CAnimCameraObj camera;auto name=r.take(80);std::memcpy(camera.name,name.data(),80);camera.pivot=r.pod<NTempest::C3Vector>();r.take(12);camera.targetPivot=r.pod<NTempest::C3Vector>();while(r.pos<end){const auto tag=r.pod<std::uint32_t>();if(tag==FourCC('K','C','T','R')){MDLKEYTRACK<NTempest::C3Vector>t;ReadBinaryTrack(r,t,mdl.sequences);AddKeyFrames(camera.translation,t);}else if(tag==FourCC('K','C','R','L')){MDLKEYTRACK<float>t;ReadBinaryTrack(r,t,mdl.sequences);AddKeyFrames(camera.roll,t);}else if(tag==FourCC('K','T','T','R')){MDLKEYTRACK<NTempest::C3Vector>t;ReadBinaryTrack(r,t,mdl.sequences);AddKeyFrames(camera.targetTranslation,t);}else if(tag==FourCC('K','V','I','S')){MDLKEYTRACK<float>t;ReadBinaryTrack(r,t,mdl.sequences);AddKeyFrames(camera.visibility,t);}else throw std::runtime_error("unknown camera animation track");if(r.pos>end)throw std::runtime_error("camera track exceeds object");}mdl.cameras.push_back(std::move(camera));}if(r.left())throw std::runtime_error("trailing camera data");}
void ReadMaterials(std::span<const std::byte>payload,MDLDATA&mdl){ByteReader r{payload};const auto materials=r.pod<std::uint32_t>();(void)r.pod<std::uint32_t>();unsigned layerId=0;for(unsigned m=0;m<materials;++m){const auto materialStart=r.pos;const auto materialSize=r.pod<std::uint32_t>();const auto materialEnd=materialStart+materialSize;if(materialSize<12||materialEnd>r.bytes.size())throw std::runtime_error("invalid material animation size");(void)r.pod<std::uint32_t>();const auto layers=r.pod<std::uint32_t>();if(!layers)throw std::runtime_error("material has no layers");for(unsigned i=0;i<layers;++i){const auto layerStart=r.pos;const auto layerSize=r.pod<std::uint32_t>();const auto layerEnd=layerStart+layerSize;if(layerSize<28||layerEnd>materialEnd)throw std::runtime_error("invalid material layer size");r.take(24);CAnimMaterialLayer layer;layer.layerId=layerId++;while(r.pos<layerEnd){const auto tag=r.pod<std::uint32_t>();if(tag==FourCC('K','M','T','A')){MDLKEYTRACK<float>t;ReadBinaryTrack(r,t,mdl.sequences);AddKeyFrames(layer.visibility,t);}else if(tag==FourCC('K','M','T','F')){MDLKEYTRACK<unsigned>t;ReadBinaryTrack(r,t,mdl.sequences);AddKeyFrames(layer.flip,t);}else throw std::runtime_error("unknown material layer track");if(r.pos>layerEnd)throw std::runtime_error("material track exceeds layer");}mdl.materials.push_back(std::move(layer));}if(r.pos!=materialEnd)throw std::runtime_error("material size mismatch");}if(r.left())throw std::runtime_error("material section size mismatch");}
void ReadTextureAnimations(std::span<const std::byte>payload,MDLDATA&mdl){ByteReader r{payload};const auto count=r.pod<std::uint32_t>();mdl.textureAnims.reserve(count);for(unsigned i=0;i<count;++i){const auto start=r.pos;const auto size=r.pod<std::uint32_t>();if(size<4||size>r.bytes.size()-start)throw std::runtime_error("invalid texture animation size");MDLKEYTRACK<NTempest::C3Vector>translation,scale;MDLKEYTRACK<NTempest::C4Quaternion>rotation;while(r.pos<start+size){auto tag=r.pod<std::uint32_t>();if(tag==FourCC('K','T','A','T'))ReadBinaryTrack(r,translation,mdl.sequences);else if(tag==FourCC('K','T','A','R'))ReadBinaryQuaternionTrack(r,rotation,mdl.sequences);else if(tag==FourCC('K','T','A','S'))ReadBinaryTrack(r,scale,mdl.sequences);else throw std::runtime_error("unknown texture animation track");}CAnimTransform out;AddKeyFrames(out.translation,translation);AddKeyFrames<NTempest::C4QuaternionCompressed>(out.rotation,rotation);AddKeyFrames(out.scale,scale);mdl.textureAnims.push_back(std::move(out));}if(r.left())throw std::runtime_error("trailing texture animation data");}
void ReadGeosetAnimations(std::span<const std::byte>payload,MDLDATA&mdl){ByteReader r{payload};const auto count=r.pod<std::uint32_t>();mdl.geosets.reserve(count);for(unsigned i=0;i<count;++i){const auto start=r.pos;const auto size=r.pod<std::uint32_t>();if(size<28||size>r.bytes.size()-start)throw std::runtime_error("invalid geoset animation size");CAnimGeoset out;out.sgGeosetId=r.pod<std::uint32_t>();r.take(20);while(r.pos<start+size){auto tag=r.pod<std::uint32_t>();if(tag==FourCC('K','G','A','O')){MDLKEYTRACK<float>t;ReadBinaryTrack(r,t,mdl.sequences);AddKeyFrames(out.visibility,t);}else if(tag==FourCC('K','G','A','C')){MDLKEYTRACK<C3Color>t;ReadBinaryTrack(r,t,mdl.sequences);AddKeyFrames(out.color,t);}else throw std::runtime_error("unknown geoset animation track");if(r.pos>start+size)throw std::runtime_error("geoset track exceeds object");}mdl.geosets.push_back(std::move(out));}if(r.left())throw std::runtime_error("trailing geoset animation data");}
MDLDATA DecodeBinaryMdl(std::span<const std::byte>file,unsigned flags){(void)flags;MDLDATA mdl;ByteReader r{file};if(r.left()>=4){std::uint32_t magic=0;std::memcpy(&magic,file.data(),4);if(magic==FourCC('M','D','L','X'))r.pos=4;}while(r.left()){if(r.left()<8)throw std::runtime_error("truncated animation chunk header");const auto tag=r.pod<std::uint32_t>();const auto size=r.pod<std::uint32_t>();auto payload=r.take(size);if(tag==FourCC('S','E','Q','S'))ReadSequences(payload,mdl);else if(tag==FourCC('G','L','B','S'))ReadGlobalSequences(payload,mdl);else if(tag==FourCC('P','I','V','T'))ReadPivotPoints(payload,mdl);else if(tag==FourCC('M','T','L','S'))ReadMaterials(payload,mdl);else if(tag==FourCC('B','O','N','E'))ReadBones(payload,mdl,false);else if(tag==FourCC('H','T','S','T'))ReadBones(payload,mdl,true);else if(tag==FourCC('L','I','T','E'))ReadLights(payload,mdl);else if(tag==FourCC('H','E','L','P'))ReadHelpers(payload,mdl);else if(tag==FourCC('A','T','C','H'))ReadAttachments(payload,mdl);else if(tag==FourCC('P','R','E','2'))ReadEmitters(payload,mdl);else if(tag==FourCC('R','I','B','B'))ReadRibbons(payload,mdl);else if(tag==FourCC('E','V','T','S'))ReadEvents(payload,mdl);else if(tag==FourCC('C','A','M','S'))ReadCameras(payload,mdl);else if(tag==FourCC('T','X','A','N'))ReadTextureAnimations(payload,mdl);else if(tag==FourCC('G','E','O','A'))ReadGeosetAnimations(payload,mdl);}return mdl;}
}
bool AnimBuild(CAnimData&out,std::span<const std::byte>file,unsigned flags){auto mdl=DecodeBinaryMdl(file,flags);return AnimBuild(out,mdl,flags);}std::shared_ptr<CAnimData>AnimBuild(std::span<const std::byte>file,unsigned flags){auto data=AnimCreate();AnimBuild(*data,file,flags);return data;}
